@@ -2641,6 +2663,8 @@ void hisi_sas_remove(struct platform_device *pdev)
 	sas_unregister_ha(sha);
 	sas_remove_host(shost);
 
+	hisi_sas_free_irqs(hisi_hba);
+
 	hisi_sas_free(hisi_hba);
 	scsi_host_put(shost);
 }
